from pathlib import Path
from html import escape
import os
ROOT=Path(__file__).resolve().parents[1]
DOCS=ROOT/"docs"
ML="machine-learning"; SL=ML+"/supervised-learning"; REG=SL+"/regression"; CLS=SL+"/classification"; DL="deep-learning"
def link(current,target): return os.path.relpath(DOCS/target,DOCS/current).replace(os.sep,"/")+"/"
def card(href,title,desc,num="01",tag="Interactive guide",cta="Explore the guide"):
 return f'<a class="card" href="{href}"><span class="number">{num} / EXPLORE</span><span class="pill">{tag}</span><h3>{title}</h3><p>{desc}</p><span class="go">{cta} ↗</span></a>'
def section(id,kicker,title,body,intro=""):
 return f'<section class="section" id="{id}"><div class="section-heading"><div><span class="eyebrow">{kicker}</span><h2>{title}</h2></div><p>{intro}</p></div>{body}</section>'
def details(items): return '<div class="details-grid">'+"".join(f'<details><summary>{t}</summary>{b}</details>' for t,b in items)+'</div>'
def formula(s): return f'<div class="formula">{s}</div>'
def flow(items): return '<div class="flow">'+'<span aria-hidden="true">→</span>'.join(f'<div><b>0{i+1}</b><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate(items))+'</div>'
def quiz(question,options):
 return '<div class="quiz" data-quiz><span class="eyebrow">Check your intuition</span><h3>'+question+'</h3><div class="quiz-options">'+''.join(f'<button type="button" data-correct="{str(c).lower()}" aria-pressed="false" data-feedback="{escape(f,quote=True)}">{t}</button>' for t,c,f in options)+'</div><p class="quiz-feedback" role="status">Choose an answer to reveal the reasoning.</p></div>'
def slider(name,label,min,max,value,step=".01"):
 return f'<label class="control" for="lab-{name}"><span class="label-row">{label}<output for="lab-{name}">{value}</output></span><input id="lab-{name}" name="{name}" type="range" min="{min}" max="{max}" value="{value}" step="{step}"></label>'
def metric(key,label): return f'<div class="metric"><span>{label}</span><b data-value="{key}">—</b></div>'
def lab(kind,title,controls,legend,note):
 return f'<div class="playground" data-lab="{kind}"><div class="lab-bar"><b>{title}</b><span>LIVE EXPERIMENT / SYNTHETIC DATA</span></div><div class="lab-grid"><div class="plot-area"><svg class="plot" viewBox="0 0 560 355" role="img" aria-label="{escape(title)}"></svg><div class="legend">{legend}</div></div><div class="controls">{controls}<p class="lab-note">{note}</p></div></div></div>'
def dot(color,text): return f'<span><i style="background:{color}"></i>{text}</span>'
def complexity(split=False):
 controls=slider("degree","Polynomial degree",1,9,3,"1")+slider("noise","Noise amplitude",0,.25,.08)
 if split: controls+=slider("split","Training examples",10,30,12,"1")
 controls+='<div class="metrics">'+metric("train","Training MSE")+metric("test","Held-out MSE")+'</div><p class="lab-note" data-value="diagnosis"></p>'
 return lab("complexity","How much complexity is enough?",controls,dot("#92baff","Training samples")+dot("#ffcc7e","Held-out samples")+dot("#a3f0c1","Fitted polynomial"),"The polynomial is refitted when you move a slider. Held-out targets use a separate deterministic noise sequence. This is a small illustrative sample, not a benchmark.")
def regression_lab():
 controls=slider("slope","Slope m",0,1.2,.35)+slider("intercept","Intercept b",0,.6,.3)+'<button class="primary" type="button" data-action="fit">Find the best line ↗</button><div class="metrics">'+metric("mse","Mean squared error")+metric("mae","Mean absolute error")+'</div><p class="lab-note" data-value="equation"></p>'
 return lab("regression","Fit a line. Watch the residuals.",controls,dot("#92baff","Observed target")+dot("#a3f0c1","Prediction")+dot("#ffcc7e","Residual"),"Try making the residuals small across all points. The button computes the ordinary least-squares solution; the sliders display it rounded to two decimals. Inputs and targets use normalized units.")
def classification_lab():
 controls=slider("threshold","Decision threshold",0,1,.5)+'<div class="metrics">'+metric("precision","Precision")+metric("recall","Recall")+metric("fp","False positives")+metric("fn","False negatives")+'</div><p class="lab-note">TP: <span data-value="tp"></span> · TN: <span data-value="tn"></span> · Accuracy: <span data-value="accuracy"></span></p>'
 return lab("classification","One model. Many decision policies.",controls,dot("#a3f0c1","Actually positive")+dot("#f7a0b5","Actually negative")+dot("#ffcc7e","Decision threshold"),"Points to the right of the threshold are predicted positive. Raising the threshold trades recall for fewer positive predictions. Precision can fluctuate on this finite sample; N/A means no positive predictions.")
def network_lab():
 controls=slider("x1","Input x₁",-1,1,.7)+slider("x2","Input x₂",-1,1,.2)+slider("gain","Hidden weight & bias scale",.2,3,1,.1)+'<label class="control" for="activation"><span class="label-row">Hidden activation</span><select id="activation" name="activation"><option value="tanh">tanh</option><option value="relu">ReLU</option></select></label><button type="button">Run forward pass ↗</button><div class="metrics">'+metric("logit","Output logit")+metric("probability","Positive probability")+'</div><p class="lab-note">Hidden values: <span data-value="hidden"></span></p>'
 return lab("network","Inside a tiny neural network",controls,dot("#a3f0c1","Positive weight")+dot("#f7a0b5","Negative weight"),"A fixed 2 → 3 → 1 network, not a trained classifier. Each hidden unit combines both inputs, applies the selected activation, and passes its value to a sigmoid output. Edge width shows the unscaled weight magnitude.")
def artwork(kind):
 grid=''.join(f'<path d="M{x} 35V305 M35 {x}H465" stroke="#2b4151" stroke-width=".5" opacity=".4"/>' for x in range(65,450,45))
 if kind in ("network","home"):
  nodes=[(65,110),(65,230),(210,70),(210,170),(210,270),(355,110),(355,230),(450,170)]
  edges=[(i,j) for i in range(2) for j in range(2,5)]+[(i,j) for i in range(2,5) for j in range(5,7)]+[(5,7),(6,7)]
  art=''.join(f'<line class="travel" x1="{nodes[i][0]}" y1="{nodes[i][1]}" x2="{nodes[j][0]}" y2="{nodes[j][1]}" stroke="#a3f0c1" stroke-width="1.3" opacity=".5"/>' for i,j in edges)
  art+=''.join(f'<circle class="pulse" style="animation-delay:{i*.2}s" cx="{x}" cy="{y}" r="{15 if i<7 else 22}" fill="#1e3c43" stroke="{["#a3f0c1","#92baff","#ffcc7e"][i%3]}" stroke-width="2"/>' for i,(x,y) in enumerate(nodes))
  art+='<text x="36" y="325">INPUT</text><text x="189" y="325">REPRESENT</text><text x="391" y="325">PREDICT</text>'
 elif kind=="classification":
  art='<path d="M250 45Q170 150 310 300" fill="none" stroke="#ffcc7e" stroke-width="2" class="travel"/>'
  for i in range(34):
   x=60+(i*67)%370;y=60+(i*47)%225;c="#a3f0c1" if x<230 else "#f7a0b5"
   art+=f'<circle cx="{x}" cy="{y}" r="5" fill="{c}" opacity=".9"/>'
  art+='<text x="65" y="325">CLASS A</text><text x="340" y="325">CLASS B</text>'
 else:
  art='<path d="M50 280C130 280 160 90 250 155S360 245 450 60" fill="none" stroke="#a3f0c1" stroke-width="3" class="travel"/>'
  for i in range(20):
   x=55+i*20;y=270-i*9+((i*23)%65)-30
   art+=f'<circle cx="{x}" cy="{y}" r="4.5" fill="#92baff"/>'
  art+='<text x="40" y="325">OBSERVATIONS</text><text x="340" y="325">A LEARNED RULE</text>'
 return f'<div class="hero-art"><svg viewBox="0 0 500 355" role="img" aria-label="Conceptual illustration of {kind}; decorative, not measured data"><g>{grid}</g><g font-family="monospace" font-size="10" fill="#aebed0">{art}</g></svg><div class="art-caption"><span>A SMALL IDEA. MADE VISIBLE.</span><span>INTERACTIVE SERIES / LAB</span></div></div>'
def page(path,title,hero,kicker,lead,kind,body,crumbs,ribbon):
 prefix=link(path,"")
 nav=''.join(f'<a href="{link(path,p)}"'+(' aria-current="page"' if path==p else '')+f'>{t}</a>' for p,t in [("","Explore"),(ML,"Machine learning"),(DL,"Deep learning")])
 crumb=''.join(f'<a href="{link(path,p)}">{t}</a><span aria-hidden="true">/</span>' for p,t in crumbs)+f'<span aria-current="page">{title}</span>'
 html=f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{escape(lead,quote=True)}"><meta name="theme-color" content="#0c111b"><title>{title} | Interactive Series</title><link rel="stylesheet" href="{prefix}assets/css/site.css"><script src="{prefix}assets/js/homepages.js" defer></script></head>
<body><a href="#main" class="skip">Skip to content</a><header class="topbar"><div class="shell header-inner"><a class="brand" href="{prefix}"><span class="brand-icon" aria-hidden="true">∿</span>Interactive Series<span class="pill">FIELD NOTES + LABS</span></a><nav class="topnav" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main" class="shell"><nav class="crumbs" aria-label="Breadcrumb">{crumb}</nav><section class="hero"><div><div class="kicker">{kicker}</div><h1>{hero}</h1><p class="lead">{lead}</p><div class="actions"><a class="button primary" href="#playground">Open the playground ↗</a><a class="button" href="#learn">Follow the learning path ↓</a></div></div>{artwork(kind)}</section>
<div class="ribbon">{''.join(f'<div><strong>{t}</strong><span>{d}</span></div>' for t,d in ribbon)}</div>{body}</main>
<footer class="shell footer"><div><strong>Interactive Series</strong><p>Make an assumption. Change a parameter. See what follows.</p></div><div><a href="{prefix}">Back to the full collection ↗</a><p>Built for curiosity. All experiments run in your browser.</p><button type="button" class="motion-toggle" data-motion aria-pressed="false">Pause motion</button></div></footer></body></html>"""
 destination=DOCS/path/"index.html";destination.parent.mkdir(parents=True,exist_ok=True);destination.write_text(html,encoding="utf-8")
home_cards=card(link("",ML),"Machine learning","From examples to general rules. Understand prediction, generalization, regression, and classification.","01","9 in-depth lessons")+card(link("",DL),"Deep learning","From a weighted sum to learned representations. Trace signals through a network and understand how it learns.","02","Interactive foundation")
home_lab=lab("explorer","Same data idea. Three different questions.",'<label class="control" for="task"><span class="label-row">What are we trying to learn?</span><select id="task"><option value="regression">Predict a number · regression</option><option value="classification">Predict a category · classification</option><option value="clustering">Discover groups · clustering</option></select></label><p class="lab-note" data-value="explanation"></p>',dot("#92baff","Synthetic observations"),"These are conceptual sketches, not models trained in this widget. Use the subject guides to fit models and inspect their errors.")
body=section("learn","01 / Choose a direction","Big ideas. Small experiments.",'<div class="cards two">'+home_cards+'</div>',"Start from the question you want to answer. Each guide connects visual intuition with the mathematics underneath.")
body+=section("method","02 / How to use this collection","Learn with a hypothesis.",flow([("Notice a pattern","Read the picture before the equation. Ask what changes and what stays fixed."),("Make a prediction","Guess what a slider will do before moving it. Being surprised is useful."),("Test the mechanism","Inspect errors, thresholds, or activations. Connect the result to the rule."),("Transfer the idea","Open a full lesson and explain the behavior on a different example.")]))
body+=section("playground","03 / Your first experiment","What does “learning” mean?",home_lab,"A model is a rule inferred from data. The kind of rule depends on the question, the available supervision, and how success is measured.")
body+=section("foundations","04 / A shared language","Four things to keep separate.",'<div class="reading"><div><h3>Data and representation</h3><p>A dataset contains observations. A feature is the representation you expose to the model: age, a word count, a pixel value, or an embedding. A target is the answer you want the model to predict. A good representation makes useful structure accessible; a misleading one can encode leakage or irrelevant shortcuts.</p><h3>Model and parameters</h3><p>A model family specifies the rules you allow. Parameters are the values learned within that family. A straight line has a slope and an intercept; a neural network has weight matrices and bias vectors. Choosing a richer family gives the optimizer more freedom, not a guarantee of better predictions.</p></div><div><h3>Objective and optimization</h3><p>The loss assigns a cost to a prediction. Optimization searches for parameter values that reduce that cost. Squared error punishes large numerical mistakes; log loss penalizes assigning low probability to the observed class. Your objective is a modeling decision, not a universal definition of usefulness.</p><h3>Evaluation and generalization</h3><p>A model can remember the examples it sees. The real question is whether it works on examples it has not used to learn or tune itself. Keep training, validation, and final testing distinct, and ask whether the evaluation data represents the environment where predictions will be used.</p></div></div>')
body+=section("math","05 / Go one layer deeper","The common mathematical thread.",details([("Empirical risk: turning examples into an objective",formula("θ̂ = arg min<sub>θ</sub> [ (1/n) Σᵢ ℓ(f<sub>θ</sub>(xᵢ), yᵢ) + λΩ(θ) ]")+"<p>Here xᵢ is an input, yᵢ its target, f is the model, ℓ is a per-example loss, and Ω penalizes complexity. λ controls the strength of that penalty. This supervised-learning template covers many models, but not every learning problem.</p>"),("Why a beautiful fit can be a bad model","<p>Observed data mixes signal with sampling variation and noise. A flexible model can fit both. Training error measures agreement with known examples; generalization error concerns new examples from a relevant distribution. A low training loss alone establishes neither robustness nor causal understanding.</p>")]))
body+=section("check","06 / Make it stick","A quick intuition check.",quiz("A model gets every training example right. What do you know?",[("It will generalize well",False,"Not yet. It may have memorized the training set. Evaluate on representative examples that were not used to fit or tune it."),("It fits those examples",True,"Exactly. Perfect training performance says the model fits those examples. Generalization requires independent evidence.")]))
page("","Interactive Series","Understand it.<br><em>Then change it.</em>","An open collection of interactive explainers","Explore the ideas behind machine learning and deep learning through visual experiments, detailed explanations, and mathematics you can put to work.","home",body,[],[("Visual intuition","Diagrams that explain the mechanism"),("Working experiments","Move a control. Observe the consequence."),("Mathematical depth","Equations, assumptions, and trade-offs")])
body=section("learn","01 / The map","Find the learning problem.",'<div class="cards two">'+card(link(ML,SL),"Supervised learning","Learn a relationship from inputs paired with targets. Choose regression for numbers or classification for categories.","01","Start here")+card(link(ML,DL),"Deep learning","Explore a family of models that composes many transformations. Neural networks can learn with supervised, self-supervised, or other objectives.","02","Model family")+'</div><div class="callout"><strong>Two different axes</strong><p>Supervised and unsupervised describe the learning signal. Deep learning describes a model family. A deep neural network can be trained with supervised labels; these categories are not mutually exclusive.</p></div>')
body+=section("paradigms","02 / What supervision is available?","The signal shapes the task.",'<div class="table-wrap"><table><thead><tr><th>Approach</th><th>Learning signal</th><th>Example</th><th>Watch out for</th></tr></thead><tbody><tr><td>Supervised</td><td>Input–target pairs</td><td>Predict demand or classify a message</td><td>Label quality, leakage, distribution shift</td></tr><tr><td>Unsupervised</td><td>Structure in inputs</td><td>Cluster similar observations</td><td>A useful grouping is not automatically a true category</td></tr><tr><td>Self-supervised</td><td>Targets constructed from the data</td><td>Predict a masked token</td><td>Pretraining objectives may differ from downstream needs</td></tr><tr><td>Reinforcement learning</td><td>Rewards from sequential interaction</td><td>Learn a control policy</td><td>Delayed feedback, exploration, and reward design</td></tr></tbody></table></div>')
body+=section("playground","03 / Fit versus generalize","When flexibility goes too far.",complexity(),"Raise the polynomial degree, then add noise. The training samples and held-out samples come from the same underlying curve, but their noise differs.")
body+=section("workflow","04 / A reliable workflow","Treat evaluation as part of modeling.",flow([("Frame","Define the prediction time, target, population, and practical cost of mistakes."),("Split","Reserve evaluation data before fitting preprocessing or choosing a model."),("Learn","Fit a baseline, train candidate models, and tune on validation data."),("Evaluate","Measure on the untouched test set; inspect slices and monitor change.")])+'<div class="reading"><div><h3>Start with a baseline</h3><p>A simple constant, linear model, or small tree establishes whether extra complexity buys anything. Compare against the same split and metric. A sophisticated model that cannot beat a sensible baseline may be learning noise or optimizing the wrong objective.</p></div><div><h3>Choose the right split</h3><p>A random split assumes observations can reasonably be treated as exchangeable. Time series usually need chronological evaluation. Repeated observations from a patient, customer, or device often need grouped splits. Otherwise information can flow between sets and inflate performance.</p></div></div>')
body+=section("math","05 / Under the hood","Capacity is only half the story.",details([("Bias, variance, and irreducible noise",formula("Expected squared error = bias² + variance + noise")+"<p>For squared-error prediction at a fixed input, under a standard additive-noise setup, this decomposition averages over possible training datasets. Bias is systematic mismatch; variance is sensitivity to the sample. The playground uses one fixed sample, so it illustrates the trade-off rather than estimating this decomposition.</p>"),("Regularization and the effective model",formula("Objective = mean training loss + λ × penalty")+"<p>Regularization changes which solutions are preferred. L2 penalties discourage large weights; other constraints, early stopping, and data augmentation can also shape effective complexity. Scaling features matters when a penalty depends on coefficient magnitude.</p>"),("Validation is a limited resource","<p>Repeatedly choosing models based on the same validation set gradually adapts your choices to it. Keep a final test set for a one-time assessment after the procedure is fixed. Cross-validation can improve estimates for small datasets, but preprocessing must be fitted within each fold.</p>"),("Prediction is not causation","<p>A feature can predict an outcome because of a common cause, selection effects, or a proxy relationship. Changing that feature may not change the outcome in the predicted way. Causal claims require additional assumptions and an appropriate study design.</p>")]))
page(ML,"Machine Learning","From examples<br>to <em>general rules.</em>","Field guide / Machine learning","A model learns patterns from data. The hard part is deciding which patterns will survive beyond the examples it has already seen.","curve",body,[("","Home")],[("The central question","Will it work on new examples?"),("The core tension","Fit the signal without chasing noise"),("The practical habit","Compare against a useful baseline")])
body=section("learn","01 / Choose your target","A number, or a category?",'<div class="cards two">'+card(link(SL,REG),"Regression","Estimate a continuous quantity: temperature, revenue, travel time, or a measured response. Study residuals and the size of errors.","01","3 complete lessons")+card(link(SL,CLS),"Classification","Assign probabilities or labels to categories: spam or not spam, a species, or a product type. Study decision thresholds and kinds of errors.","02","6 complete lessons")+'</div>')
body+=section("mechanism","02 / Inputs → prediction → feedback","What makes learning supervised?",flow([("Observe","Collect x: the features available at prediction time."),("Predict","Use fθ(x) to produce a number, score, or probability."),("Compare","Evaluate a loss against the known target y."),("Update","Adjust parameters to reduce the average training loss.")])+'<div class="reading"><div><h3>Labels define the question</h3><p>“Will this customer leave within 30 days?” and “How many days until the customer leaves?” use similar inputs but imply different targets, losses, and evaluation. Write down the prediction horizon and how labels are collected before choosing an algorithm.</p></div><div><h3>Labels can be imperfect</h3><p>Annotation disagreement, missing outcomes, delayed feedback, and historical decisions can affect the targets. A model learns patterns in recorded labels; it does not automatically recover an ideal, unbiased ground truth. Inspect how labels were produced and which cases are absent.</p></div></div>')
body+=section("playground","03 / Learn from a sample","More data changes the fit.",complexity(True),"Change the number of training examples as well as degree and noise. The held-out set stays fixed for a given noise setting; training points are resampled at evenly spaced positions.")
body+=section("evaluation","04 / Keep the roles distinct","Three datasets. Three jobs.",'<div class="cards"><article class="card"><span class="number">01 / TRAIN</span><h3>Learn the parameters</h3><p>Use training examples to fit model weights, imputation rules, feature scaling, and other learned transformations.</p></article><article class="card"><span class="number">02 / VALIDATE</span><h3>Choose the procedure</h3><p>Use validation data to compare features, hyperparameters, regularization, and decision thresholds.</p></article><article class="card"><span class="number">03 / TEST</span><h3>Estimate performance</h3><p>After choices are fixed, evaluate once on independent test data that reflects the intended deployment setting.</p></article></div>'+quiz("Should a feature scaler be fitted before splitting the whole dataset?",[("Yes, it has no labels",False,"Even without labels, the scaler would learn the evaluation distribution. Fit it on the training set, then apply the learned transformation to validation and test data."),("No, fit it on training data",True,"Correct. Preprocessing is part of the learned procedure. Fit it on training data only, or within each training fold during cross-validation.")]))
body+=section("math","05 / The objective","Learning as risk minimization.",details([("What exactly gets minimized?",formula("R̂(θ) = (1/n) Σᵢ ℓ(fθ(xᵢ), yᵢ)")+"<p>The empirical risk averages loss over observed examples. Minimizing it approximates minimizing expected loss on future examples only when the data and modeling assumptions support that transfer. Regularization adds preferences about plausible solutions.</p>"),("Parameters versus hyperparameters","<p>Parameters are fitted from training data: slopes, tree splits, or network weights. Hyperparameters configure the procedure: tree depth, neighbor count, regularization strength, or learning rate. Hyperparameters are usually chosen using validation performance; the test set must not become a tuning loop.</p>"),("Common losses for different outputs",formula("Regression: ℓ = (y − ŷ)²<br>Binary classification: ℓ = −y log p − (1−y) log(1−p)")+"<p>Squared error emphasizes large residuals. Binary cross-entropy evaluates probabilities assigned to binary labels. The probability threshold used to make a hard decision is a separate choice from the loss used to learn probabilities.</p>"),("Distribution shift breaks easy assumptions","<p>Future inputs, label frequencies, or the relationship between input and target can change. A test score is evidence about a particular evaluation distribution. Monitor meaningful slices and changes over time, and decide when recalibration or retraining is needed.</p>")]))
page(SL,"Supervised Learning","Examples with answers.<br><em>Predictions without them.</em>","Field guide / Supervised learning","Learn a mapping from observed inputs to known targets, then test whether that mapping holds for new examples. Start by choosing the type of answer you need.","curve",body,[("","Home"),(ML,"Machine learning")],[("Inputs","Features available at prediction time"),("Targets","Known outcomes used for learning"),("Feedback","A loss that measures prediction error")])
reg_lessons=[("linear-regression","Simple Linear Regression","Start with slope, intercept, residuals, and least squares."),("polynomial-regression","Polynomial Regression","Use powers of x to represent curvature; inspect model degree and overfitting."),("regularization","Ridge, Lasso & ElasticNet","Control coefficient size and compare shrinkage with sparse solutions.")]
body=section("learn","01 / Your learning path","From a line to a controlled curve.",'<div class="cards">'+''.join(card(s+"/",t,d,f"{i+1:02}","Interactive lesson","Open the full explainer") for i,(s,t,d) in enumerate(reg_lessons))+'</div>')
body+=section("playground","02 / Build the intuition","Every prediction leaves a residual.",regression_lab(),"A regression model predicts a numerical target. Move the slope and intercept to see how the prediction rule changes, and how every point contributes to the loss.")
body+=section("interpret","03 / Read the model","A slope is a statement about change.",'<div class="reading"><div><h3>Slope and intercept</h3><p>In ŷ = mx + b, the slope m is the predicted change in the target for one unit of x. The intercept b is the predicted target at x = 0. An intercept may be mathematically necessary even when zero lies outside the meaningful input range. With multiple features, each coefficient is interpreted conditional on the other included features.</p><h3>Residuals are evidence</h3><p>A residual is the observed target minus the prediction: e = y − ŷ. A visible curve in residuals suggests missing nonlinear structure. A widening spread suggests nonconstant variance. Large residuals deserve investigation; they can be valid rare cases, data errors, or signs that the model is inappropriate.</p></div><div><h3>Interpolation versus extrapolation</h3><p>Predicting inside the observed input range is interpolation. Predicting outside it is extrapolation, where the chosen functional form does much more of the work. A polynomial can look convincing in-range and diverge rapidly beyond the data. Always inspect the domain where a prediction is being requested.</p><div class="callout"><strong>Association is not an intervention</strong><p>A positive coefficient does not prove that increasing the feature causes the target to increase. Confounding and selection can create predictive relationships without that causal meaning.</p></div></div></div>')
body+=section("metrics","04 / Decide what error means","Choose the metric for the consequence.",'<div class="table-wrap"><table><thead><tr><th>Metric</th><th>Definition</th><th>Interpretation and caveat</th></tr></thead><tbody><tr><td>MAE</td><td>mean |y − ŷ|</td><td>Average absolute error in target units; less sensitive to extreme residuals than MSE.</td></tr><tr><td>MSE / RMSE</td><td>mean (y − ŷ)² / √MSE</td><td>Emphasizes large errors. RMSE returns to target units.</td></tr><tr><td>R²</td><td>1 − SSE / SST</td><td>Relative to predicting the evaluated targets’ mean. Can be negative; undefined when target variance is zero.</td></tr></tbody></table></div>')
body+=section("math","05 / From intuition to equations","What least squares is doing.",details([("Derive the best-fitting line",formula("m̂ = Σᵢ(xᵢ − x̄)(yᵢ − ȳ) / Σᵢ(xᵢ − x̄)²<br>b̂ = ȳ − m̂x̄")+"<p>Set the derivatives of the sum of squared residuals with respect to m and b to zero. The denominator must be nonzero: if all x values are identical, slope and intercept are not separately identifiable. The playground’s fit button uses this closed-form solution.</p>"),("Polynomial regression is still linear in its parameters",formula("ŷ = β₀ + β₁x + β₂x² + ⋯ + βₖxᵏ")+"<p>The curve is nonlinear in x, but the prediction is a linear combination of learned coefficients. You can fit it with linear least squares on transformed features. High-degree power bases can also be numerically ill-conditioned; feature scaling and better-conditioned bases matter.</p>"),("Ridge and Lasso change the objective",formula("Ridge: mean squared error + λΣⱼβⱼ²<br>Lasso: mean squared error + λΣⱼ|βⱼ|")+"<p>Ridge shrinks coefficients smoothly. Lasso can set some coefficients exactly to zero. The intercept is commonly left unpenalized, and scaling features is important for comparable penalties. ElasticNet combines both penalties. Select λ with validation, not final test performance.</p>"),("Fitting versus statistical inference","<p>Least squares can be computed without Gaussian noise. Stronger assumptions matter for properties of estimators, standard errors, and prediction intervals. Normality, independence, constant variance, and correct mean specification play different roles; a point prediction alone does not quantify uncertainty.</p>")]))
body+=section("check","06 / Make it stick","Which loss reacts more strongly?",quiz("An error doubles from 2 to 4. What happens to its squared-error contribution?",[("It doubles",False,"The absolute error doubles, but squared error changes from 4 to 16."),("It quadruples",True,"Correct: 2² = 4 and 4² = 16. This is why squared error gives large residuals disproportionate influence.")]))
page(REG,"Regression","Predict a number.<br><em>Understand the error.</em>","Learning path / Regression","Fit relationships between inputs and numerical outcomes. Start with a straight line, learn to read residuals, and control complexity as your models become more expressive.","curve",body,[("","Home"),(ML,"Machine learning"),(SL,"Supervised learning")],[("3 complete lessons","Linear → polynomial → regularized"),("Live fitting lab","Change the line and inspect the loss"),("Beyond the fit","Residuals, metrics, and assumptions")])
cls_lessons=[("logistic-regression","Logistic Regression","Model a probability with a sigmoid and learn a linear decision boundary."),("knn","K-Nearest Neighbors","Let nearby observations vote; explore neighborhood size and distance."),("decision-trees","Decision Trees","Partition feature space with interpretable, sequential decisions."),("random-forests","Random Forests","Average diverse trees to reduce the variance of individual trees."),("support-vector-machines","Support Vector Machines","Use margins and kernels to reason about separating boundaries."),("xgboost","XGBoost","Build an additive ensemble of trees that improves an objective step by step.")]
body=section("learn","01 / Your learning path","Six ways to draw a boundary.",'<div class="cards">'+''.join(card(s+"/",t,d,f"{i+1:02}","Interactive lesson","Open the full explainer") for i,(s,t,d) in enumerate(cls_lessons))+'</div>',"Different models encode different assumptions about how categories occupy feature space. Start with logistic regression, then compare local, tree-based, and margin-based approaches.")
body+=section("playground","02 / Probability is not a decision","Move the threshold. Change the mistakes.",classification_lab(),"A classifier can produce a score or probability. A decision policy turns that output into an action. Those are different steps, and changing the policy changes which errors you make.")
body+=section("reasoning","03 / Know the cost of being wrong","There is more than one kind of mistake.",'<div class="reading"><div><h3>False positives and false negatives</h3><p>A false positive predicts the positive class when the actual class is negative. A false negative misses an actual positive. In spam filtering, a false positive may hide a legitimate message; a false negative lets spam through. The best operating point depends on these consequences, not just an arbitrary threshold of 0.5.</p><h3>Precision and recall</h3><p>Precision asks: among the predicted positives, how many are actually positive? Recall asks: among all actual positives, how many did we detect? Raising a threshold can reduce the number of positive predictions, but precision need not move monotonically in a finite sample.</p></div><div><h3>Accuracy can conceal failure</h3><p>If positives are rare, predicting the majority class can achieve high accuracy while detecting none of the cases you care about. Inspect the confusion matrix, per-class performance, and the base rate. For imbalanced tasks, precision–recall behavior is often especially informative.</p><h3>Calibration answers another question</h3><p>Among cases assigned a probability near 0.8, roughly 80% should be positive if the model is well calibrated on that population. Good ranking does not imply calibration. Probability quality and threshold choice must be evaluated separately.</p></div></div>')
body+=section("math","04 / Under the hood","From a score to a probability.",details([("Logistic regression: a linear log-odds model",formula("z = wᵀx + b<br>p(y = 1 | x) = σ(z) = 1 / (1 + e<sup>−z</sup>)<br>log[p / (1−p)] = wᵀx + b")+"<p>The sigmoid maps a real-valued score to (0,1). A fixed threshold produces a linear boundary in the chosen feature representation. Adding nonlinear features can make the boundary nonlinear in the original inputs.</p>"),("Cross-entropy rewards honest probabilities",formula("ℓ(p,y) = −y log p − (1−y) log(1−p)")+"<p>A confidently wrong prediction incurs a large loss. Unlike accuracy, this loss responds to probability changes even when the predicted label stays the same. Implementations should use numerically stable logit-based computations rather than taking logs of rounded probabilities.</p>"),("The confusion matrix and derived metrics",formula("Precision = TP / (TP + FP)<br>Recall = TP / (TP + FN)<br>F1 = 2TP / (2TP + FP + FN)")+"<p>Each metric summarizes a different trade-off. Precision is undefined when no positive predictions are made; recall is undefined when there are no actual positives. F1 combines precision and recall but ignores true negatives and does not encode every application’s error costs.</p>"),("Multiclass versus multilabel","<p>Multiclass classification chooses one among several mutually exclusive categories, often using softmax probabilities. Multilabel classification allows multiple labels per example, often using a separate sigmoid output for each label. The target representation, loss, and metrics must match the task.</p>")]))
body+=section("check","05 / Make it stick","Can accuracy tell the whole story?",quiz("Only 1% of examples are positive. An always-negative model has 99% accuracy. Is it useful for detecting positives?",[("Yes, 99% is excellent",False,"It detects zero positives: recall is 0. A majority-class baseline can score highly on accuracy while failing the intended task."),("No, its recall is zero",True,"Exactly. Compare with a baseline and inspect positive-class recall, precision, and costs before judging the model.")]))
page(CLS,"Classification","Predict a category.<br><em>Choose your trade-off.</em>","Learning path / Classification","Learn how models separate classes, estimate probabilities, and turn uncertain scores into decisions. A useful classifier gets the right kinds of mistakes under control.","classification",body,[("","Home"),(ML,"Machine learning"),(SL,"Supervised learning")],[("6 complete lessons","From logistic models to boosted trees"),("Threshold playground","See precision and recall change"),("Decisions with context","Costs, calibration, and class balance")])
body=section("learn","01 / A guided foundation","Follow a signal through the network.",'<div class="cards">'+card("#playground","The forward pass","Combine inputs with weights, add a bias, apply an activation, and repeat.","01","Experiment","Trace the activations")+card("#training","Learning by gradients","Connect a prediction error to parameter updates through the chain rule.","02","Mechanism","Understand training")+card("#architectures","Choose an architecture","Compare dense networks, convolutions, and attention by their structural assumptions.","03","Concept map","Explore the model families")+'</div>')
body+=section("intuition","02 / The central idea","Learn the representation, too.",'<div class="reading"><div><h3>Composition creates expressiveness</h3><p>A neural network applies a sequence of parameterized transformations. Early layers can build intermediate features that later layers combine. These representations are learned jointly for the training objective, instead of all being specified by hand. Depth refers to composing layers, not simply having many parameters.</p><h3>Nonlinearity matters</h3><p>Stacking only affine transformations still yields a single affine transformation. Activation functions such as ReLU or tanh allow the network to represent nonlinear relationships. Their derivatives also affect how gradients travel during training.</p></div><div><h3>A family, not a learning regime</h3><p>Neural networks can learn from labeled examples, targets constructed from the data, rewards, or combinations of objectives. “Deep learning” describes a model family; “supervised learning” describes the feedback available. These ideas overlap rather than compete.</p><div class="callout"><strong>Start small enough to inspect</strong><p>The experiment below has just one hidden layer. It is a shallow network designed to expose the mechanics. Deep networks repeat and extend these operations across many layers.</p></div></div></div>')
body+=section("playground","03 / Open the black box","Every activation is a calculation.",network_lab(),"Change the inputs, hidden activation, or weight scale. The hidden values and output probability are recomputed from the displayed network, so you can trace the dependency from end to end.")
body+=section("training","04 / From prediction to learning","A forward pass is only half the loop.",flow([("Forward","Compute activations and the prediction from the current parameters."),("Loss","Compare the prediction with a target using a task-appropriate objective."),("Backward","Apply the chain rule to compute gradients of loss with respect to parameters."),("Update","Move parameters using an optimizer; repeat over batches of examples.")])+'<div class="reading"><div><h3>Backpropagation is differentiation</h3><p>Backpropagation efficiently computes derivatives through the computational graph. It does not itself choose how to update parameters. Gradient descent, momentum, and Adam are optimization procedures that use those derivatives. Keeping these roles separate helps make sense of the training loop.</p></div><div><h3>Optimization is not generalization</h3><p>A falling training loss means the optimizer is improving the training objective. It does not prove that the representation is useful on new data. Hold out evaluation data, monitor overfitting, and consider regularization, augmentation, or early stopping. Data quality and evaluation design still matter at scale.</p></div></div>')
body+=section("architectures","05 / Architectural assumptions","Different structures for different data.",'<div class="table-wrap"><table><thead><tr><th>Architecture</th><th>Core operation</th><th>Useful structural idea</th><th>Important limitation</th></tr></thead><tbody><tr><td>Dense / MLP</td><td>Affine maps + nonlinearities</td><td>Combine a fixed set of features</td><td>Does not inherently encode spatial or sequence structure</td></tr><tr><td>Convolutional network</td><td>Shared local filters</td><td>Reuse pattern detectors across positions</td><td>Receptive field and boundary handling affect context</td></tr><tr><td>Recurrent network</td><td>State updated across steps</td><td>Represent sequential dependencies</td><td>Long-range gradients and sequential computation can be difficult</td></tr><tr><td>Transformer</td><td>Attention + feed-forward layers</td><td>Let token representations exchange context</td><td>Standard full attention has quadratic pairwise interactions in sequence length</td></tr></tbody></table></div>')
body+=section("math","06 / The mathematical machinery","Track the values. Then the derivatives.",details([("The exact network in the playground",formula("h = φ(g · (Wx + b))<br>W = [[1.2, −0.8], [−0.7, 1.3], [0.9, 0.6]]<br>b = [0.2, −0.1, −0.4]<br>z = 0.8h₁ − 1.1h₂ + 0.7h₃ − 0.2<br>p = σ(z)")+"<p>The slider g scales the hidden weights and biases. φ is tanh or ReLU; the output always uses sigmoid. These fixed weights were chosen for illustration and have not been learned from data. A probability-shaped output alone does not imply calibrated predictions.</p>"),("The chain rule makes learning possible",formula("∂L/∂w = (∂L/∂a) · (∂a/∂z) · (∂z/∂w)<br>w ← w − η ∂L/∂w")+"<p>For a unit with z = wx + b and a = φ(z), the local factor ∂z/∂w is x. The activation derivative gates how the downstream gradient reaches w. η is the learning rate; too large a step can destabilize training, while too small a step can slow progress.</p>"),("Activation functions shape values and gradients",formula("ReLU(z) = max(0,z)<br>tanh′(z) = 1 − tanh²(z)")+"<p>ReLU has zero derivative for negative inputs and derivative one for positive inputs; implementations choose a convention at zero. A unit stuck on the negative side may stop receiving useful gradients. Tanh is smooth but saturates toward −1 or 1, where derivatives become small. Try increasing the hidden scale and observe saturation.</p>"),("Why linear layers alone are not enough",formula("W₂(W₁x + b₁) + b₂ = (W₂W₁)x + (W₂b₁ + b₂)")+"<p>Composing affine layers collapses to one affine map. Nonlinear activations prevent this collapse and enable richer decision functions. Greater expressiveness still requires appropriate data, optimization, and evaluation to become useful.</p>"),("Batch, epoch, and learning rate","<p>A batch is the subset of examples used for an update. An epoch is one pass through the training set. The learning rate controls the update scale. Batch size affects gradient noise and computational behavior; it is not interchangeable with the number of epochs.</p>"),("Attention in one equation",formula("Attention(Q,K,V) = softmax(QKᵀ / √dₖ)V")+"<p>Queries and keys determine normalized weights over values. The scaling helps control dot-product magnitude. Positional information and masks constrain how tokens interact. Attention weights are part of the computation, not automatically a complete explanation of the model’s decision.</p>")]))
body+=section("check","07 / Make it stick","What makes the stack nonlinear?",quiz("You stack five affine layers with no activation between them. What function can the stack represent?",[("An arbitrary nonlinear function",False,"Without nonlinear activations, the composition collapses to a single affine map, regardless of the number of layers."),("A single affine transformation",True,"Exactly. Multiplying the weight matrices and combining biases produces one affine map. Nonlinear activations add the missing expressive power.")]))
page(DL,"Deep Learning","Many small operations.<br><em>Rich representations.</em>","Field guide / Deep learning","See how networks compose simple transformations into flexible models. Trace a forward pass, understand gradients, and connect the mechanics to modern architectures.","network",body,[("","Home")],[("A network you can inspect","Two inputs, three hidden units, one output"),("The training loop","Forward → loss → backward → update"),("A foundation for depth","Activations, representations, architectures")])
